//! 🎟️ Actual native header evidence binds the original boxed type, address and allocation layout.
use crate::{ErasedSnapshotRetirement,OriginalRetirementFailure,RetainedAllocationEffect,RetainedCloneStep,RetainedCloneProgress,RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value_control_contract::{OriginalEffectReply,OriginalEffectReplyComplete};
/// 🧷️ Declares the complete native destructor work and extra release extent of one actual boxed owner.
pub struct RetirementHeaderRelease{kind:std::any::TypeId,address:usize,layout:std::alloc::Layout,extra_release:usize,extra_work:u64}
impl RetirementHeaderRelease{
 /// ⚠️ The actual owner's full terminal Drop must be bounded, callback-free, nonallocating and nonunwinding; extra_release and extra_work must exactly include every release and action beyond the native Box shell, and all payload/child/reply owners must already be gone.
 pub unsafe fn native<T:ErasedSnapshotRetirement>(owner:&T,extra_release:usize,extra_work:u64)->Self{Self{kind:std::any::TypeId::of::<T>(),address:std::ptr::from_ref(owner).cast::<()>()as usize,layout:std::alloc::Layout::new::<T>(),extra_release,extra_work}}
 fn validate<T:ErasedSnapshotRetirement+?Sized>(&self,owner:&T)->Result<(),ValueError>{if std::any::Any::type_id(owner)!=self.kind||std::ptr::from_ref(owner).cast::<()>()as usize!=self.address||std::alloc::Layout::for_value(owner)!=self.layout||!owner.terminal_is_empty(){return Err(ValueError::invariant("native retirement header differs from its actual boxed owner"))}Ok(())}
 pub fn demand<T:ErasedSnapshotRetirement+?Sized>(&self,owner:&T)->Result<RetirementDemand,ValueError>{self.validate(owner)?;let release_bytes=self.layout.size().checked_add(self.extra_release).ok_or_else(||ValueError::invariant("native header release extent overflow"))?;Ok(RetirementDemand{copy_bytes:std::mem::size_of::<Option<Box<T>>>(),release_bytes,depth:1,..Default::default()})}
 pub fn work(&self)->Result<u64,ValueError>{self.extra_work.checked_add(1).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"native header release work overflow"))}
 /// 📤️ Releases the same validated resident terminal header through its borrowed reply.
 pub fn release_into<'r,T:ErasedSnapshotRetirement+?Sized>(&self,slot:&mut Option<Box<T>>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{let owner=slot.as_ref().ok_or_else(||ValueError::invariant("native header owner is absent"))?;let demand=self.demand(owner.as_ref())?;let work=self.work()?;if effect.remaining_work_units()?<work||!crate::retained_clone_grant_admits(effect.grant(),demand){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(work){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"native header release exceeded original work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}drop(slot.take());Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:demand.release_bytes,..Default::default()}))))}
}
